contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address baseToken_,
        address nft_,
        uint128 virtualBaseTokenReserves_,
        uint128 virtualNftReserves_,
        uint56 changeFee_,
        uint16 feeRate_,
        bytes32 merkleRoot_,
        bool useStolenNftOracle_,
        bool payRoyalties_
    ) public {
        bool firstReverted;
        try c.initialize(
            baseToken_,
            nft_,
            virtualBaseTokenReserves_,
            virtualNftReserves_,
            changeFee_,
            feeRate_,
            merkleRoot_,
            useStolenNftOracle_,
            payRoyalties_
        ) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        address observedAfterFirst = c.baseToken();

        bool secondReverted;
        try c.initialize(
            address(0xdead),
            nft_,
            virtualBaseTokenReserves_,
            virtualNftReserves_,
            changeFee_,
            feeRate_,
            merkleRoot_,
            useStolenNftOracle_,
            payRoyalties_
        ) {
            secondReverted = false;
        } catch {
