        } else {
            assert(secondReverted == false || c.initialized() == false);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address baseToken_,
        address nft_,
        uint128 virtualBaseTokenReserves_,
        uint128 virtualNftReserves_,
        uint56 changeFee_,
        uint16 feeRate_,
        bytes32 merkleRoot_,
        bool useStolenNftOracle_,
        bool payRoyalties_,
        address baseToken2_
    ) public {
        require(true);

        // First successful initialization (fresh pool, feeRate within bounds).
        require(feeRate_ <= 5000);
        c.initialize(
            baseToken_,
            nft_,
            virtualBaseTokenReserves_,
            virtualNftReserves_,
            changeFee_,
            feeRate_,
            merkleRoot_,
            useStolenNftOracle_,
            payRoyalties_
        );

        address observedAfterFirst = c.baseToken();
        bool initializedAfterFirst = c.initialized();

        // Attempt to re-initialize with a different base token; must revert.
        bool secondReverted;
        try c.initialize(
            baseToken2_,
            nft_,
            virtualBaseTokenReserves_,
            virtualNftReserves_,
            changeFee_,
            feeRate_,
            merkleRoot_,
            useStolenNftOracle_,
            payRoyalties_
        ) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(initializedAfterFirst && observedAfterFirst == baseToken_ && secondReverted && c.baseToken() == baseToken_);
    }
}

